'use strict';

// MODULES //

var Promise = global.Promise;
var deepHasProp = require( '@stdlib/assert/deep-has-property' );
var fac = require( '@stdlib/plot/unicode/bar_chart/lib' );
var max = require( '@stdlib/math/base/special/fast/max' );
var data = require( './facets.json' );
var count = 0;
var ind;
var test = new visulizeIt( 'rate', 'shape', undefined, [ { 'scope': 'stacks' } ] );


// FUNCTIONS //

/**
* Function to creat delay.
*
* @private
* @param {number} ms - mili second
* @returns {void} plotBase instance
*/
function sleep(ms) {
	return new Promise(function delayHandler(resolve) {
		setTimeout(resolve, ms);
	});
}

/**
* main Function to run with dealy on each iteration in loop.
*
* @private
* @returns {void} plotBase instance
*/
async function runWithDelay() {
	for ( ind = 0; ind < data.length; ind++) {
		await sleep(1000);
		test.push(data[ind]);
		console.log( count+=1 );
		test.render();
	}
}

/**
* Function to with dealy on each iteration in loop.
*
* @private
* @param {number} ms - milli second
* @returns {void} plotBase instance
*/
function normalRun() {
	for ( ind = 0; ind < data.length; ind++) {
		test.push(data[ind]);
	}
	test.render();
}

/**
* State manager which manage the state of options for bar chart.
*
* @private
* @param {string} yaxis - property name of facets for y axis on plot
* @param {string} xaxis - property name of facets for x axis on plot
* @param {string} bar - property name of facets for grouped bar on plot
* @param {Array} filter - Array used to filter the data facets
* @returns {void}
*/
function visulizeIt( yaxis, xaxis, bar, filter ) {
	this.yaxis = yaxis;
	this.xaxis = xaxis;
	this.bar = bar;
	this.filter = filter;
	this.structuredData = {
	};
	this.opt = {
		'data': [],
		'barsPerLabel': 1,
		'barsColor': [ 'Fgreen', 'Fblack', 'Fred', 'Fblack', 'Fred', 'Fgreen' ],
		'barWidth': 5,
		'barGap': 2
	};
	this.barSet = new Set();
	this.inst = fac( this.opt );
	var i;
	var barArr;
	var inst;
	var count = 0;
	var x;
	var y;
	var b = 'bar';
	if ( !this.bar ) {
		this.opt.barsPerLabel = 1;
		this.barSet.add(b);
	}
	var obj;

	this.push = function push( data ) {
		if ( isFollowFilter( data, filter ) ) {
			x = ( isNumeric( data[ xaxis ] ) ) ? Number( data[ xaxis ] ): data[ xaxis ];
			y = ( isNumeric( data[ yaxis ] ) ) ? Number( data[ yaxis ] ): data[ yaxis ];
			if ( this.bar ) {
				b = ( isNumeric( data[ this.bar ] ) ) ? Number( data[ this.bar ] ): data[ this.bar ];
				this.barSet.add( data[ this.bar ] );
			}
			if ( this.structuredData[ x ] ) {
				obj = this.structuredData[ x ];
				if ( obj[ b ] ) {
					// Avg out the y value
					obj[ b ] = ( y + obj[ b ] ) / 2;
				}
				else {
					obj[ b ] = y;
				}
			}
			else {
				this.structuredData[ x ] = {};
				this.structuredData[ x ][ b ] = y;
			}
		}
	};

	this.render = function render( ) {
		var finalArr = [];
		var temp;
		var key;

		this.opt.barsPerLabel = this.barSet.size;
		for ( key in this.structuredData ) {
			if ( this.structuredData[ key ] === null ) {
				continue;
			}
			temp = [];
			temp.push( key );
			for ( b of this.barSet ) {
				if ( !this.structuredData[ key ][ b ] ) {
					temp.push( 0 );
				}
				else {
					temp.push( this.structuredData[ key ][ b ] );
				}
			}
			finalArr.push( temp );
		}
		this.opt[ 'data' ] = finalArr;
		this.inst.data = finalArr;
		this.inst.barsPerLabel = this.barSet.size;
		console.log( this.inst.render() );
	};
}

/**
* Function to vailidate the data agains filter.
*
* @private
* @param {object} data - data facet
* @param {Array} filterArr - filter array
* @returns {boolean} is data follow the filter
*/
function isFollowFilter( data, filterArr ) {
	var key;
	var i;
	for ( i = 0; i < filterArr.length; i++ ) {
		if ( typeof filterArr[ i ] === 'string' ) {
			if ( !deepHasProp( data, filterArr[ i ] ) ) {
				return false;
			}
		}
		if ( typeof filterArr[ i ] === 'object' ) {
			for ( key in filterArr[ i ] ) {
				if ( !data[ key ] || data[ key ] !== filterArr[ i ][ key ] ) {
					return false;
				}
			}
		}
	}
	return true;
}

/**
* Assert to check weather string is numeric .
*
* @private
* @param {String} str - string
* @returns {void}
*/
function isNumeric(str) {
	return typeof str === 'string' && Number.isFinite(Number(str));
}


// MAIN

normalRun()
